/* Adapter between the retained legacy economy and Decide Fate's save envelope. */
(function(g){'use strict';
const E=g.DecideLegacyEconomy||(typeof require==='function'?require('./legacy-economy.js'):null);
const kinds=E.PRICEABLE_CONTENT_TYPES,copy=x=>JSON.parse(JSON.stringify(x));
function need(ok,message){if(!ok)throw Error(message);}
function validate(value){if(value===undefined)return {v:1,items:[],gearStash:[]};need(value&&value.v===1&&Array.isArray(value.items)&&value.items.length<=2000&&value.items.every(x=>typeof x==='string'&&x.trim().length>0&&x.length<=160)&&Array.isArray(value.gearStash)&&value.gearStash.length<=200&&value.gearStash.every(x=>x&&E.GEAR_CONTENT_TYPES.includes(x.refType)&&typeof x.name==='string'&&x.name.trim().length>0&&x.name.length<=160),'ข้อมูลคลังจากฐานข้อมูลไม่ถูกต้อง');return copy(value);}
function ready(s){need(s.character&&!s.dead&&!s.event&&!s.expedition,'กลับจากสนามและจบเหตุการณ์ก่อนใช้บริการ');need(Number.isSafeInteger(s.gold)&&s.gold>=0,'จำนวนเหรียญไม่ถูกต้อง');}
function party(s){const inv=validate(s.catalogInventory);return [{id:'hero',items:inv.items,gearStash:inv.gearStash}];}
function find(rows,kind,id){const row=rows.find(x=>x.kind===kind&&x.id===id);need(row&&row.enabled!==false,'ไม่พบรายการที่เปิดใช้งาน');return row;}
function commit(s,r){need(r.success,r.reason||'ทำรายการไม่สำเร็จ');need(Number.isSafeInteger(r.gold)&&r.gold>=0&&r.gold<=1e9,'จำนวนเหรียญเกินขอบเขต');const next=copy(s),p=r.party[0];next.catalogInventory=validate({v:1,items:p.items||[],gearStash:p.gearStash||[]});next.gold=r.gold;return {snapshot:next,result:r};}
function quantity(n){need(Number.isSafeInteger(n)&&n>=1&&n<=99,'จำนวนต้องเป็นจำนวนเต็ม 1–99');}
function buy(s,rows,npcId,kind,itemId,n=1){ready(s);quantity(n);need(kinds.includes(kind),'หมวดนี้ซื้อขายไม่ได้');const npc=find(rows,'npc',npcId),item=find(rows,kind,itemId);return commit(s,E.resolvePurchaseItem(npc,item,kind,n,party(s),s.gold,'hero',item.buyPrice));}
function sell(s,rows,npcId,kind,itemId,n=1){ready(s);quantity(n);need(kinds.includes(kind),'หมวดนี้ซื้อขายไม่ได้');const npc=find(rows,'npc',npcId),item=find(rows,kind,itemId),location=E.GEAR_CONTENT_TYPES.includes(kind)?'stash':'inventory';return commit(s,E.resolveSellOffer(npc,item,kind,n,party(s),s.gold,location,'hero',null));}
function craft(s,rows,npcId,recipeId){ready(s);const npc=find(rows,'npc',npcId),recipe=find(rows,'recipe',recipeId);need(Number.isSafeInteger(Number(recipe.goldCost))&&Number(recipe.goldCost)>=0&&Number.isSafeInteger(Number(recipe.resultQuantity))&&Number(recipe.resultQuantity)>=1&&Number(recipe.resultQuantity)<=99,'ค่าสูตรปรุงไม่ถูกต้อง');const counts=new Map();for(const kv of recipe.ingredients||[]){const n=Number(kv.value);need(typeof kv.key==='string'&&kv.key.trim()&&Number.isSafeInteger(n)&&n>0&&n<=2000,'ส่วนผสมไม่ถูกต้อง');counts.set(kv.key.trim(),(counts.get(kv.key.trim())||0)+n);}const normalized={...recipe,ingredients:[...counts].map(([key,n])=>({key,value:String(n)}))};return commit(s,E.resolveCraftRecipe(normalized,npc,party(s),s.gold,rows.filter(x=>x.kind==='item'),'hero'));}
function use(s,rows,itemId){ready(s);const item=find(rows,'item',itemId),p=party(s),owned=p[0].items.includes(item.name);need(owned,'ไม่มีไอเท็มนี้ในคลัง');need(Number.isFinite(Number(item.value))&&Number(item.value)>=0,'ค่าไอเท็มไม่ถูกต้อง');const N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null),target={id:'hero',hp:s.hp,maxHp:s.character.design===1?N.maxHp(s.character):100,mp:s.mp,maxMp:s.maxMp};const result=E.resolveItemEffect(item,target,target,{});need(result.ok,result.reason);need(result.effects.some(x=>x.delta>0),'ค่าพลังเต็มแล้ว ไม่ใช้ไอเท็ม');const next=copy(s);for(const effect of result.effects)next[effect.type==='hp'?'hp':'mp']=effect.next;const remaining=E.removeOneSharedItem(p,item.name)[0];next.catalogInventory=validate({v:1,items:remaining.items,gearStash:remaining.gearStash});return {snapshot:next,result};}
function useInCombat(s,rows,itemId){
 need(s.character&&!s.dead&&s.expedition?.status==='active','ไม่มีสนามที่กำลังต่อสู้');
 const next=copy(s),e=next.expedition;let C=g.DecideCombatRules||(typeof require==='function'?require('./combat-data.js'):null);if(!C.tactical&&typeof require==='function')C=require('./tactical-systems.js');C.tactical.init(e);
 const p=C.hero(e);need(p&&p.side==='player'&&p.hp>0,'สมาชิกที่สั่งการต้องยังต่อสู้ได้');need(p.action>=1,'ต้องมีอย่างน้อย 1 AP');need(!p.casting,'กำลังร่ายเวท ต้องปล่อยหรือยกเลิกก่อน');need(!p.effects?.stun&&!p.effects?.frozen,'ติดสตันหรือแช่แข็ง ใช้ไอเท็มไม่ได้');
 const item=find(rows,'item',itemId),inv=validate(next.catalogInventory);need(inv.items.includes(item.name),'ไม่มีไอเท็มนี้ในคลัง');need(Number.isFinite(Number(item.value))&&Number(item.value)>=0,'ค่าไอเท็มไม่ถูกต้อง');
 const target={id:p.id,hp:p.hp,maxHp:p.maxHp,mp:p.mana,maxMp:p.maxMana},result=E.resolveItemEffect(item,target,target,{});need(result.ok,result.reason);need(result.effects.some(x=>x.delta>0),'ค่าพลังเต็มแล้ว ไม่ใช้ไอเท็ม');
 for(const effect of result.effects)p[effect.type==='hp'?'hp':'mana']=effect.next;
 inv.items.splice(inv.items.indexOf(item.name),1);next.catalogInventory=validate(inv);p.action-=1;p.moving=false;
 const message=p.name+' ใช้ '+item.name+' • '+result.effects.map(x=>(x.type==='hp'?'HP':'MP')+' +'+x.delta).join(' / ')+' • 1 AP';e.log.unshift(message);e.log=e.log.slice(0,30);C.tactical.perceive(e,p);
 return {snapshot:next,result:{...result,message,targetId:p.id}};
}
const api={validate,party,buy,sell,craft,use,useInCombat};g.DecideCatalogEconomy=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
